 async function parseBackup(file){if(file.size<BACKUP_MAGIC.length+4)throw new Error('バックアップファイルが短すぎます。');const prefix=await file.slice(0,BACKUP_MAGIC.length+4).arrayBuffer();if(new TextDecoder().decode(prefix.slice(0,BACKUP_MAGIC.length))!==BACKUP_MAGIC)throw new Error('このアプリのバックアップファイルではありません。');const len=new DataView(prefix).getUint32(BACKUP_MAGIC.length,true),start=BACKUP_MAGIC.length+4+len;if(len<=0||len>MAX_HEADER||start>file.size)throw new Error('バックアップのヘッダーが不正です。');let manifest;try{manifest=JSON.parse(await file.slice(BACKUP_MAGIC.length+4,start).text());}catch{throw new Error('バックアップの管理情報を読み取れません。');}if(manifest?.format!=='sg-listening-backup'||manifest.version!==1||!Array.isArray(manifest.tracks)||manifest.tracks.length!==TOTAL||!Array.isArray(manifest.audio)||manifest.audio.length>TOTAL)throw new Error('バックアップ形式に対応していません。');const tracks=manifest.tracks.map(normalizeTrack);const ids=new Set(tracks.map(t=>t.id));if(ids.size!==TOTAL)throw new Error('バックアップの音声枠に重複があります。');const audioIds=new Set();let offset=0;const audioRecords=[];for(const a of manifest.audio){const t=tracks.find(t=>t.id===a.id);if(!t?.hasAudio||audioIds.has(a.id)||!Number.isSafeInteger(a.size)||a.size<=0||!Number.isSafeInteger(a.offset)||a.offset!==offset||start+a.offset+a.size>file.size||typeof a.type!=='string'||a.type.length>100||t.size!==a.size)throw new Error('バックアップの音声データが不正、または破損しています。');audioIds.add(a.id);audioRecords.push({id:a.id,blob:file.slice(start+a.offset,start+a.offset+a.size,a.type)});offset+=a.size;}if(start+offset!==file.size||tracks.filter(t=>t.hasAudio).some(t=>!audioIds.has(t.id)))throw new Error('バックアップの音声データが不足、または余分なデータがあります。');return {tracks,settings:normalizeSettings(manifest.settings),audioRecords};}
 async function restoreBackup(file){if(!file)return;setBusy('バックアップを確認しています');let parsed;try{parsed=await parseBackup(file);}catch(e){clearBusy();handleError(e);return;}clearBusy();const ok=await ask({title:'ライブラリを復元しますか？',message:`バックアップの音声 ${parsed.audioRecords.length}本と学習記録を復元します。\n現在の音声・進捗・設定は、すべてこのバックアップに置き換わります。\n必要なデータは先にバックアップしてください。`,confirm:'現在の内容を置き換えて復元',danger:true});if(!ok)return;setBusy('バックアップを復元しています');try{await checkRestoreCapacity(parsed);}catch(e){clearBusy();handleError(e);return;}await saveProgress(true);restoring=true;clearPlayer();try{await write(['tracks','audio','settings'],tx=>{tx.objectStore('tracks').clear();tx.objectStore('audio').clear();tx.objectStore('settings').clear();for(const t of parsed.tracks)tx.objectStore('tracks').put(t);for(const a of parsed.audioRecords)tx.objectStore('audio').put(a);tx.objectStore('settings').put({key:'main',...parsed.settings});});state.tracks=parsed.tracks;state.settings=parsed.settings;state.stage=[];state.libraryDay=state.settings.selectedDay;state.sleepUntil=0;state.sleepEnd=false;$('sleepSelect').value='off';applySettings();renderStage();navigate('home');toast(`${parsed.audioRecords.length}本の音声と学習記録を復元しました。`);}catch(e){handleError(e);}finally{restoring=false;clearBusy();}const last=getTrack(state.settings.lastTrackId);if(last?.hasAudio)loadTrack(last.id,{autoplay:false}).catch(handleError);}
 async function toggleFlag(id,key){const t=getTrack(id);if(!t?.hasAudio)return;const previous={...t};t[key]=!t[key];if(key==='completed'){if(!t.completed&&t.position>=t.duration-.1){t.position=0;if(state.currentId===id)audio.currentTime=0;}t.progressUpdatedAt=Date.now();if(state.currentId===id)writeRecovery();}try{await putTrack(t);render();toast(key==='review'?(t.review?'復習リストに追加しました。':'復習リストから外しました。'):(t.completed?'学習済みにしました。':'未学習に戻しました。'));}catch(e){Object.assign(t,previous);handleError(e);render();}}
