 async function readEntry(entry,path=''){if(entry.isFile){return new Promise((resolve,reject)=>entry.file(file=>resolve([{file,path:path+file.name}]),reject));}if(entry.isDirectory){const reader=entry.createReader();let all=[];while(true){const entries=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));if(!entries.length)break;for(const child of entries)all.push(...await readEntry(child,path+entry.name+'/'));if(all.length>2000)throw new Error('フォルダが大きすぎます。音声ファイルだけを選択してください。');}return all;}return [];}
