 async function init(){try{db=await openDB();const [tracks,s]=await Promise.all([read('tracks'),read('settings','main')]);for(const t of tracks){const normalized=normalizeTrack(t),i=state.tracks.findIndex(x=>x.id===t.id);if(i>=0)state.tracks[i]=normalized;}state.settings=normalizeSettings(s);try{const r=JSON.parse(localStorage.getItem(RECOVERY_KEY)||'null'),t=getTrack(r?.id);if(t?.hasAudio&&Number.isFinite(r.at)&&r.at>t.progressUpdatedAt&&Number.isFinite(r.position)&&r.position>=0){t.position=t.duration?Math.min(t.duration,r.position):r.position;t.completed=r.completed===true;t.progressUpdatedAt=r.at;await putTrack(t);}}catch{}state.libraryDay=state.settings.selectedDay;applySettings();render();refreshStorage();const last=getTrack(state.settings.lastTrackId);if(last?.hasAudio)await loadTrack(last.id,{autoplay:false});applyRoute();document.documentElement.dataset.ready='true';initPlatform();}catch(e){console.error(e);$('appShell').innerHTML=`<section class="fatal-box"><h1>保存領域を開けませんでした</h1><p>公開URLをChromeまたはSafariの通常モードで開いてください。シークレットモードやファイルのプレビュー画面では保存できない場合があります。</p><p>データを削除する前に、保存済みのバックアップがあるか確認してください。</p><code>${esc(friendlyError(e))}</code></section>`;}}
