  if(h==='#admin'){state.view='admin';}
  else if(h==='#review'){state.view='review';}
  else if(h==='#home'||/^#day-(?:[1-9]|1[0-4])$/.test(h)){state.view='home';if(h.startsWith('#day-')){state.settings.selectedDay=Number(h.slice(5));saveSettings().catch(reportSaveError);}}
